function normalize(text) { return text.replace(/\r\n/g, "\n"); }
function shaText(text) { return crypto.createHash("sha256").update(normalize(text)).digest("hex"); }
function git(wt, args) { return cp.execFileSync("git", ["-C", wt, ...args], {encoding:"utf8"}).trim(); }
function replaceOnce(text, before, after, label) {
  const first=text.indexOf(before);
  if(first<0) throw new Error(`STOP: patch anchor not found: ${label}`);
  if(text.indexOf(before, first+1)>=0) throw new Error(`STOP: patch anchor is not unique: ${label}`);
  return text.slice(0,first)+after+text.slice(first+before.length);
}
function writeWithEol(file, normalizedText, originalText) {
  const eol = originalText.includes("\r\n") ? "\r\n" : "\n";
  fs.writeFileSync(file, normalizedText.replace(/\n/g,eol), "utf8");
}
function statusPaths(wt) {
  const raw=git(wt,["status","--porcelain=v1","--untracked-files=all"]);
  if(!raw) return [];
  return raw.split(/\r?\n/).filter(Boolean).map(line => ({line, file: line.slice(3).trim().replace(/\\/g,"/")}));
}
function runBin(bin, args, cwd, label) {
  const r=cp.spawnSync(bin,args,{cwd,stdio:"inherit",shell:process.platform==="win32"});
  if(r.error) throw r.error;
  if(r.status!==0) throw new Error(`STOP: ${label} failed with exit code ${r.status}.`);
}
function assertPayloads() {
  for (const [rel,b64] of Object.entries(PAYLOADS)) {
    const text=Buffer.from(b64,"base64").toString("utf8");
    if(shaText(text)!==EXPECTED_SENIOR[rel]) throw new Error(`STOP: embedded senior payload integrity failed: ${rel}`);
    if(text.includes(".replaceAll(")) throw new Error(`STOP: ES2020-incompatible replaceAll detected: ${rel}`);
  }
}

